#[test]
fn generated_go_matches_rust_and_diff_doc_is_current() {
    let fixtures = fixtures();
    let run = run_go("main", &fixtures, |s| s);
    let c = compare(&fixtures, &run);
    assert!(c.errors.is_empty(), "generated Go failed: {:#?}", c.errors);
    assert!(
        c.gen_mismatch.is_empty(),
        "generator bugs (generated Go != Rust serde output): {:#?}",
        c.gen_mismatch
    );
    assert!(
        c.gen_extra.is_empty(),
        "generated-only keys: {:?}",
        c.gen_extra
    );

    let vpath = workspace().join("docs/plan/2.2-diff-go-verdicts.json");
    let entries = parse_verdicts(&std::fs::read_to_string(&vpath).unwrap()).unwrap();
    let mut problems = verdict_problems(&c.rows, &entries);
    let doc = render(&fixtures, &c.rows, &verdict_map(&entries));
    let dpath = workspace().join("docs/plan/2.2-diff-go.md");
    if std::env::var_os("AIMUX_BLESS_DIFF").is_some() {
        write_atomic(&dpath, &doc);
    } else {
        problems.extend(doc_problem(
            std::fs::read_to_string(&dpath).ok().as_deref(),
            &doc,
        ));
    }
    assert!(problems.is_empty(), "{problems:#?}");
}

/// Mutation: rename one wire name in the generated Go (`ToolCall.toolCallId`
/// → `toolCallID`). The comparison reports exactly that one row, and the
/// generator check flags it.
#[test]
fn mutated_wire_name_is_reported_as_exactly_one_row() {
    let fixtures: Vec<Fixture> = fixtures()
        .into_iter()
        .filter(|f| f.label == "tool-call")
        .collect();
    let base = compare(&fixtures, &run_go("base", &fixtures, |s| s));
    let mutated_run = run_go("mutated", &fixtures, |s| {
        // Only types.go declares TaggedToolCall (the generated form of a
        // standalone ToolCall); other files pass through.
        let Some(start) = s.find("\ntype TaggedToolCall struct {") else {
            return s;
        };
        let end = start + s[start..].find("\n}\n").unwrap();
        let block = &s[start..end];
        let from = "`json:\"toolCallId\"`";
        assert!(block.contains(from), "{block}");
        format!(
            "{}{}{}",
            &s[..start],
            block.replacen(from, "`json:\"toolCallID\"`", 1),
            &s[end..]
        )
    });
    let mutated = compare(&fixtures, &mutated_run);
    let new: Vec<&Row> = mutated
        .rows
        .iter()
        .filter(|r| !base.rows.contains(r))
        .collect();
    assert_eq!(
        new,
        vec![&Row {
            ty: "ToolCall".into(),
            field: "toolCallId".into(),
            generated: ABSENT.into(),
            handwritten: "\"call_1\"".into(),
            truth: "\"call_1\"".into(),
        }]
    );
    assert_eq!(expected_verdict(new[0]), "生成器错");
    assert_eq!(mutated.gen_extra, vec!["ToolCall.toolCallID".to_string()]);
    // Both directions catch it: Go output != serde output, and serde
    // rejects the Go output (missing `toolCallId`).
    assert_eq!(mutated.gen_mismatch.len(), 2, "{:?}", mutated.gen_mismatch);
    assert!(
        mutated
            .gen_mismatch
            .iter()
            .all(|m| m.starts_with("tool-call:"))
    );
    assert!(mutated.gen_mismatch[0].contains("missing field `toolCallId`"));
}

/// Mutation proof for each verdict/doc check, on the real rows and the
/// committed verdicts file.
#[test]
fn verdict_and_doc_checks_each_catch_their_mutation() {
    let (f, r) = shared();
    let c = compare(f, r);
    let text =
        std::fs::read_to_string(workspace().join("docs/plan/2.2-diff-go-verdicts.json")).unwrap();
    let entries = parse_verdicts(&text).unwrap();
    assert_eq!(verdict_problems(&c.rows, &entries), Vec::<String>::new());
    let target = c
        .rows
        .iter()
        .find(|r| r.ty == "ImageResult" && r.field == "warnings")
        .unwrap();
    let at = entries
        .iter()
        .position(|e| e.ty == target.ty && e.field == target.field)
        .unwrap();

    // Missing verdict: drop the entry.
    let mut m = entries.clone();
    m.remove(at);
    assert_eq!(
        verdict_problems(&c.rows, &m),
        vec!["no verdict for ImageResult | warnings"]
    );
    // Contradicting verdict.
    let mut m = entries.clone();
    m[at].verdict = "生成器错".into();
    assert_eq!(
        verdict_problems(&c.rows, &m),
        vec!["verdict `生成器错` for ImageResult | warnings contradicts the Rust output []"]
    );
    // Orphan verdict: an entry for a row that does not exist.
    let mut m = entries.clone();
    let mut orphan = m[at].clone();
    orphan.field = "nonexistent".into();
    m.push(orphan);
    assert_eq!(
        verdict_problems(&c.rows, &m),
        vec!["orphan verdict for ImageResult | nonexistent (no such diff row)"]
    );
    // Missing `reason`: removed from the JSON text, and empty.
    let mut v: serde_json::Value = serde_json::from_str(&text).unwrap();
    v[at].as_object_mut().unwrap().remove("reason");
    let m = parse_verdicts(&v.to_string()).unwrap();
    assert_eq!(
        verdict_problems(&c.rows, &m),
        vec!["verdict for ImageResult | warnings has no reason"]
    );
    let mut m = entries.clone();
    m[at].reason = Some("  ".into());
    assert_eq!(
        verdict_problems(&c.rows, &m),
        vec!["verdict for ImageResult | warnings has no reason"]
    );
    // Stale doc. This test never reads docs/plan/2.2-diff-go.md: that file
    // is owned by generated_go_matches_rust_and_diff_doc_is_current, which
    // may rewrite it (AIMUX_BLESS_DIFF=1) while this test runs in parallel.
    // The mutation works on an in-memory scratch copy of the rendered doc.
    let doc = render(f, &c.rows, &verdict_map(&entries));
    let scratch = doc.clone();
    assert_eq!(doc_problem(Some(&scratch), &doc), None);
    let stale = scratch.replacen("手写错", "生成器错", 1);
    assert_ne!(stale, scratch);
    assert!(doc_problem(Some(&stale), &doc).is_some());
    assert!(doc_problem(None, &doc).is_some());
}

/// Untagged decode error parity (reviewer A): for null-bearing inputs the
/// generated Go must accept exactly when real serde deserialization accepts.
/// encoding/json alone accepts `null` and `[null]` as zero values. The types
/// are every untagged enum in the manifest (go_fixtures_untagged.rs, written
/// by gen_go_fixtures.py), each with `null`, `[null]` and `{"a": null}`.
fn null_parity_cases() -> Vec<Fixture> {
    let mut out = Vec::new();
    for (ty, b) in go_fixtures_untagged::untagged_types() {
        for (kind, json) in [
            ("null", json!(null)),
            ("array", json!([null])),
            ("object", json!({"a": null})),
        ] {
            out.push(Fixture {
                label: Box::leak(format!("null-{ty}-{kind}").into_boxed_str()),
                ty,
                json,
                back: Some(b),
            });
        }
    }
    out
}

/// The untagged-enum list the null-parity cases use is every untagged union
/// of the IR lowered from the current sources (the committed list is not
/// stale and misses none).
#[test]
fn null_parity_covers_every_untagged_enum() {
    let listed: BTreeSet<&str> = go_fixtures_untagged::untagged_types()
        .into_iter()
        .map(|(t, _)| t)
        .collect();
    let ir: BTreeSet<&str> = ir()
        .values()
        .filter(|t| {
            matches!(
                &t.body,
                wire::WireBody::Union {
                    repr: wire::UnionRepr::Untagged,
                    ..
                }
            )
        })
        .map(|t| t.name.as_str())
        .collect();
    assert_eq!(listed, ir);
    let cases: BTreeSet<&str> = null_parity_cases().iter().map(|f| f.ty).collect();
    assert_eq!(cases, ir);
}

/// `(label, serde accepts, generated Go accepts)` per null-parity case.
fn null_parity(mutate: impl Fn(String) -> String) -> Vec<(String, bool, bool)> {
    let cases = null_parity_cases();
    let run = run_go("nulls", &cases, mutate);
    cases
        .iter()
        .zip(&run.results)
        .map(|(f, r)| {
            assert_eq!(f.label, r.label);
            let serde_ok = (f.back.unwrap())(&f.json).is_ok();
            (f.label.to_string(), serde_ok, r.gen_err.is_empty())
        })
        .collect()
}

#[test]
fn untagged_decode_rejects_null_exactly_like_serde() {
    let got = null_parity(|s| s);
    let diverge: Vec<_> = got.iter().filter(|(_, s, g)| s != g).collect();
    assert!(diverge.is_empty(), "serde vs generated Go: {diverge:#?}");
    // Both outcomes occur, so parity is not vacuous.
    assert!(got.iter().any(|(_, s, _)| *s) && got.iter().any(|(_, s, _)| !*s));
}

/// Expected wire state of one key after a round trip.
#[derive(Debug, Clone, Copy, PartialEq)]
enum Key {
    Absent,
    Null,
}

/// The committed manifest's presence facts for an `Option` field: the
/// expected key after decoding the field `omitted` and decoding it as
/// `null`. `None` for fields whose `null` handling is not about presence.
fn presence_facts(field: &Value) -> Option<(Key, Key)> {
    let input = field["null"]["input"].as_str()?;
    let skipped = field["omittedWhen"] == json!("Option::is_none");
    let none = if skipped { Key::Absent } else { Key::Null };
    match input {
        // An explicit null reads as `None`, the same as an absent key.
        "asAbsent" => Some((none, none)),
        // `present`: absent → None, null → Some(None), written as null.
        "distinct" if skipped => Some((Key::Absent, Key::Null)),
        _ => None,
    }
}

fn key_of(v: &Value, key: &str) -> Option<Key> {
    match v.get(key) {
        None => Some(Key::Absent),
        Some(Value::Null) => Some(Key::Null),
        Some(_) => None,
    }
}

/// U1: the same field as an `omitted` sample and a `null` sample. For every
/// presence-relevant `Option` field of a covered struct type (facts read
/// from the committed `generated/manifest.json`, not from the sources),
/// serde must land on the manifest's expected key, and the generated Go
/// must accept both samples and write exactly what serde writes.
#[test]
fn omitted_and_null_samples_match_manifest_presence() {
    let manifest: Value = serde_json::from_str(
        &std::fs::read_to_string(workspace().join("tools/aimux-codegen/generated/manifest.json"))
            .unwrap(),
    )
    .unwrap();
    let types = manifest["types"].as_array().unwrap();
    let base = fixtures();
    let mut samples = Vec::new();
    let mut expect = Vec::new();
    let mut seen = BTreeSet::new();
    for f in &base {
        let (Some(back), Some(obj)) = (f.back, f.json.as_object()) else {
            continue;
        };
        if !f.label.starts_with("cov-") {
            continue;
        }
        let Some(t) = types
            .iter()
            .find(|t| t["tsName"].as_str().unwrap_or(t["name"].as_str().unwrap()) == f.ty)
        else {
            continue;
        };
        if t["shape"]["kind"] != "struct" {
            continue;
        }
        for field in t["shape"]["fields"].as_array().unwrap() {
            let wire = field["wire"].as_str().unwrap();
            let Some((omitted, null)) = presence_facts(field) else {
                continue;
            };
            if field["flatten"] == true || !seen.insert((f.ty, wire.to_string())) {
                continue;
            }
            for (kind, want) in [("omitted", omitted), ("null", null)] {
                let mut o = obj.clone();
                if kind == "omitted" {
                    o.remove(wire);
                } else {
                    o.insert(wire.into(), Value::Null);
                }
                let label: &'static str =
                    Box::leak(format!("presence-{}-{wire}-{kind}", f.ty).into_boxed_str());
                samples.push(Fixture {
                    label,
                    ty: f.ty,
                    json: Value::Object(o),
                    back: Some(back),
                });
                expect.push((label, wire.to_string(), want));
            }
        }
    }
    assert!(
        expect.iter().any(|e| e.2 == Key::Null) && expect.iter().any(|e| e.2 == Key::Absent),
        "both outcomes are exercised"
    );
    // The `present` (distinct) fields are the ones a Go `*json.RawMessage`
    // or plain pointer would collapse.
    assert!(
        expect
            .iter()
            .any(|(l, w, k)| l.starts_with("presence-EmbeddingResponse-")
                && w == "body"
                && *k == Key::Null),
        "{expect:?}"
    );
    let run = run_go("presence", &samples, |s| s);
    let mut problems = Vec::new();
    for ((f, r), (label, wire, want)) in samples.iter().zip(&run.results).zip(&expect) {
        assert_eq!(f.label, r.label);
        let truth = match (f.back.unwrap())(&f.json) {
            Ok(v) => v,
            Err(e) => {
                problems.push(format!("{label}: serde rejects the sample: {e}"));
                continue;
            }
        };
        if key_of(&truth, wire) != Some(*want) {
            problems.push(format!(
                "{label}: manifest says {want:?}, serde wrote {:?}",
                truth.get(wire.as_str())
            ));
        }
        if !r.gen_err.is_empty() {
            problems.push(format!("{label}: generated Go rejects: {}", r.gen_err));
        } else if !gen_is(r.gen_out.as_ref(), &truth, f.ty) {
            problems.push(format!(
                "{label}: serde {truth} != generated {}",
                show(r.gen_out.as_ref())
            ));
        }
    }
    assert_eq!(problems, Vec::<String>::new(), "{} samples", samples.len());
    eprintln!("presence samples: {}", samples.len());
}

// U1 review (A) items 1, 3, 5 -----------------------------------------------

/// Replace, on struct-field lines only (those with a `json:"type"` tag),
/// a `Lit*` fixed-value field type by `json.RawMessage`: the generated Go
/// as it was before `WireTy::Literal` (the fallback).
fn literal_as_fallback(s: String) -> String {
    s.lines()
        .map(|l| {
            if l.contains("`json:\"type\"`")
                && let Some(i) = l.find(" Lit")
            {
                let end = l[i + 1..].find(' ').map_or(l.len(), |e| i + 1 + e);
                format!("{} json.RawMessage{}", &l[..i], &l[end..])
            } else {
                l.to_string()
            }
        })
        .collect::<Vec<_>>()
        .join("\n")
        + "\n"
}

/// Fixed `type` tag cases. (a) `zero-*`: a Go zero value (a union with
/// only its variant tag set) encoded; serde (`wire::typed`) must accept the
/// output and the tag must be written. (b) `untagged-*`: serde's plain
/// (untagged) JSON of the value decoded and re-encoded by the generated Go;
/// the output must equal `aimux_core::wire::Tagged` of the value and serde
/// must accept it. Types: the TS-only wrappers (`TypedToolCall`,
/// `TaggedToolResult`, `TypedSource`) and the `TypeTag` forms (`Tagged*`).
fn literal_cases() -> (Vec<Fixture>, Vec<(&'static str, &'static str, Value)>) {
    use aimux_core::result::{Source, TypedToolResult};
    use aimux_core::tool::RawToolCall;
    let tc: Back = back_tagged::<ToolCall>;
    let rtc: Back = back_tagged::<RawToolCall>;
    let tr: Back = back_tagged::<TypedToolResult>;
    let src: Back = back_tagged::<Source>;
    let zero = |label, ty, back| Fixture {
        label,
        ty,
        json: Value::Null,
        back: Some(back),
    };
    let mut fixtures = vec![
        zero("zero-TypedToolCall", "TypedToolCall{}", tc),
        zero("zero-TaggedToolCall", "TaggedToolCall{}", tc),
        zero("zero-TaggedRawToolCall", "TaggedRawToolCall{}", rtc),
        zero("zero-TaggedToolResult", "TaggedToolResult{}", tr),
        zero("zero-TaggedTypedToolResult", "TaggedTypedToolResult{}", tr),
        zero(
            "zero-TypedSource-url",
            "TypedSource{Tag: \"url\", Value: gen.TypedSourceUrl{}}",
            src,
        ),
        zero(
            "zero-TypedSource-document",
            "TypedSource{Tag: \"document\", Value: gen.TypedSourceDocument{}}",
            src,
        ),
        zero(
            "zero-TaggedSource-url",
            "TaggedSource{Tag: \"url\", Value: gen.TaggedSourceUrl{}}",
            src,
        ),
        zero(
            "zero-TaggedSource-document",
            "TaggedSource{Tag: \"document\", Value: gen.TaggedSourceDocument{}}",
            src,
        ),
    ];
    fn pair<T>(v: Value) -> (Value, Value)
    where
        T: serde::Serialize + serde::de::DeserializeOwned + aimux_core::wire::TypeTag,
    {
        let t: T = serde_json::from_value(v).unwrap();
        (
            serde_json::to_value(&t).unwrap(),
            serde_json::to_value(aimux_core::wire::Tagged(&t)).unwrap(),
        )
    }
    let call = json!({"toolCallId": "c1", "toolName": "t", "input": {"a": 1}});
    let raw = json!({"toolCallId": "c1", "toolName": "t", "input": "{\"a\":1}"});
    let result = json!({"toolCallId": "c1", "toolName": "t", "output": {"ok": true}});
    let url = json!({"sourceType": "url", "id": "s1", "url": "https://example.com"});
    let doc =
        json!({"sourceType": "document", "id": "d1", "mediaType": "text/plain", "title": "T"});
    let mut tagged = Vec::new();
    for (label, ty, (plain, truth), back) in [
        (
            "untagged-TypedToolCall",
            "TypedToolCall",
            pair::<ToolCall>(call.clone()),
            tc,
        ),
        (
            "untagged-TaggedToolCall",
            "TaggedToolCall",
            pair::<ToolCall>(call),
            tc,
        ),
        (
            "untagged-TaggedRawToolCall",
            "TaggedRawToolCall",
            pair::<RawToolCall>(raw),
            rtc,
        ),
        (
            "untagged-TaggedToolResult",
            "TaggedToolResult",
            pair::<TypedToolResult>(result.clone()),
            tr,
        ),
        (
            "untagged-TaggedTypedToolResult",
            "TaggedTypedToolResult",
            pair::<TypedToolResult>(result),
            tr,
        ),
        (
            "untagged-TypedSource-url",
            "TypedSource",
            pair::<Source>(url.clone()),
            src,
        ),
        (
            "untagged-TypedSource-document",
            "TypedSource",
            pair::<Source>(doc.clone()),
            src,
        ),
        (
            "untagged-TaggedSource-url",
            "TaggedSource",
            pair::<Source>(url),
            src,
        ),
        (
            "untagged-TaggedSource-document",
            "TaggedSource",
            pair::<Source>(doc),
            src,
        ),
    ] {
        assert!(plain.get("type").is_none(), "{label}: input is untagged");
        fixtures.push(Fixture {
            label,
            ty,
            json: plain,
            back: Some(back),
        });
        tagged.push((label, ty, truth));
    }
    (fixtures, tagged)
}

/// Failing `(zero, untagged)` literal cases for the generated Go (`mutate`d).
fn literal_failures(mutate: impl Fn(String) -> String) -> (usize, Vec<String>, usize, Vec<String>) {
    let (fixtures, tagged) = literal_cases();
    let run = run_go("literal", &fixtures, mutate);
    let (mut zero, mut untagged) = (Vec::new(), Vec::new());
    let mut n_zero = 0;
    for (f, r) in fixtures.iter().zip(&run.results) {
        assert_eq!(f.label, r.label);
        let is_zero = f.label.starts_with("zero-");
        n_zero += usize::from(is_zero);
        let fail = if !r.gen_err.is_empty() {
            Some(format!("{}: generated Go: {}", f.label, r.gen_err))
        } else {
            let out = r.gen_out.clone().unwrap_or(Value::Null);
            let lit = f.back.unwrap()(&out);
            match (&lit, is_zero) {
                (Err(e), _) => Some(format!("{}: serde rejects {out}: {e}", f.label)),
                (Ok(_), true) if !out.get("type").is_some_and(Value::is_string) => {
                    Some(format!("{}: no `type` tag in {out}", f.label))
                }
                (Ok(_), false) => {
                    let truth = &tagged.iter().find(|t| t.0 == f.label).unwrap().2;
                    (out != *truth)
                        .then(|| format!("{}: Tagged {truth} != generated {out}", f.label))
                }
                _ => None,
            }
        };
        if let Some(m) = fail {
            if is_zero {
                zero.push(m);
            } else {
                untagged.push(m);
            }
        }
    }
    (n_zero, zero, fixtures.len() - n_zero, untagged)
}

/// Item 1: a `#[ts(type = "\"lit\"")]` field is a fixed value, always
/// written. Mutation: the fallback (`json.RawMessage`) writes `"type":null`
/// for a zero value and for untagged input, and every case of both classes
/// goes red.
#[test]
fn fixed_type_tag_is_always_written() {
    let (nz, zero, nu, untagged) = literal_failures(|s| s);
    assert_eq!((nz, nu), (9, 9));
    assert_eq!(
        (zero.len(), untagged.len(), &zero, &untagged),
        (0, 0, &Vec::<String>::new(), &Vec::<String>::new())
    );
    let (_, zero, _, untagged) = literal_failures(literal_as_fallback);
    assert_eq!(zero.len(), nz, "{zero:#?}");
    assert_eq!(untagged.len(), nu, "{untagged:#?}");
}

/// Every tri-state field (`null.input = distinct`) in the committed
/// manifest, enum variant fields included: `(owner label, wire)`.
fn tri_state_fields() -> Vec<(String, String)> {
    let m: Value = serde_json::from_str(
        &std::fs::read_to_string(workspace().join("tools/aimux-codegen/generated/manifest.json"))
            .unwrap(),
    )
    .unwrap();
    let mut out = Vec::new();
    for t in m["types"].as_array().unwrap() {
        let go = t["tsName"].as_str().unwrap_or(t["name"].as_str().unwrap());
        let distinct = |sh: &Value| -> Vec<String> {
            sh["fields"]
                .as_array()
                .into_iter()
                .flatten()
                .filter(|f| f["null"]["input"] == "distinct")
                .map(|f| f["wire"].as_str().unwrap().to_string())
                .collect()
        };
        for w in distinct(&t["shape"]) {
            out.push((format!("tri-{go}"), w));
        }
        for v in t["shape"]["variants"].as_array().into_iter().flatten() {
            for w in distinct(&v["shape"]) {
                out.push((format!("tri-{go}-{}", v["rust"].as_str().unwrap()), w));
            }
        }
    }
    out
}

/// Replace, on struct-field lines, `TriState[X]` + `omitzero` by `*X` +
/// `omitempty`: the generated Go with `tri_state = false`.
fn tri_state_as_pointer(s: String) -> String {
    s.lines()
        .map(|l| {
            if l.contains("`json:")
                && let Some(i) = l.find("TriState[")
            {
                let close = i + l[i..].find(']').unwrap();
                format!("{}*{}{}", &l[..i], &l[i + 9..close], &l[close + 1..])
                    .replace(",omitzero", ",omitempty")
            } else {
                l.to_string()
            }
        })
        .collect::<Vec<_>>()
        .join("\n")
        + "\n"
}

/// Tri-state fields whose omitted or null sample fails: serde must land on
/// absent / null, the generated Go must accept both samples and write
/// exactly what serde writes.
fn tri_state_red(mutate: impl Fn(String) -> String) -> (Vec<(String, String)>, BTreeSet<String>) {
    let fields = tri_state_fields();
    let owners = go_fixtures_tri::tri_state_fixtures();
    let mut samples = Vec::new();
    let mut expect = Vec::new();
    for (owner, wire) in &fields {
        let (_, ty, json, back) = owners
            .iter()
            .find(|o| o.0 == owner)
            .unwrap_or_else(|| panic!("no fixture {owner}"));
        let obj = json
            .as_object()
            .unwrap_or_else(|| panic!("{owner} is not an object"));
        assert!(obj.contains_key(wire.as_str()), "{owner}: {wire} filled");
        for (kind, want) in [("omitted", Key::Absent), ("null", Key::Null)] {
            let mut o = obj.clone();
            if kind == "omitted" {
                o.remove(wire.as_str());
            } else {
                o.insert(wire.clone(), Value::Null);
            }
            let label: &'static str = Box::leak(format!("{owner}.{wire}-{kind}").into_boxed_str());
            samples.push(Fixture {
                label,
                ty,
                json: Value::Object(o),
                back: *back,
            });
            expect.push((format!("{owner}.{wire}"), wire.clone(), want));
        }
    }
    let run = run_go("tristate", &samples, mutate);
    let mut red = BTreeSet::new();
    for ((f, r), (field, wire, want)) in samples.iter().zip(&run.results).zip(&expect) {
        assert_eq!(f.label, r.label);
        let truth = f.back.expect("tri-state owners deserialize")(&f.json)
            .unwrap_or_else(|e| panic!("{}: serde rejects the sample: {e}", f.label));
        assert_eq!(
            key_of(&truth, wire),
            Some(*want),
            "{}: manifest vs serde",
            f.label
        );
        if !r.gen_err.is_empty() || !gen_is(r.gen_out.as_ref(), &truth, f.ty) {
            red.insert(field.clone());
        }
    }
    (fields, red)
}

/// Item 3: every tri-state field in the manifest (not only those with a
/// hand-written counterpart). Mutation `tri_state = false`: every one is red.
#[test]
fn every_tri_state_field_round_trips_omitted_and_null() {
    let (fields, red) = tri_state_red(|s| s);
    let names: BTreeSet<String> = fields.iter().map(|(o, w)| format!("{o}.{w}")).collect();
    assert_eq!(names.len(), 14, "{names:#?}");
    assert!(names.contains("tri-ApiCallError.data"), "{names:#?}");
    assert!(
        names.contains("tri-AssistantContentPart-ToolApprovalRequest.inputSchemaInput"),
        "{names:#?}"
    );
    assert_eq!(red, BTreeSet::new());
    let (_, red) = tri_state_red(tri_state_as_pointer);
    assert_eq!(red, names, "mutation: every tri-state field red");
    eprintln!(
        "tri-state fields: {}, red under mutation: {}",
        names.len(),
        red.len()
    );
}

/// Item 5: integers compare exactly; only `f32` / `f64` paths by value.
#[test]
fn integers_compare_exactly_floats_by_value() {
    let none = BTreeSet::new();
    let (big, near) = (
        json!(9_007_199_254_740_993_u64),
        json!(9_007_199_254_740_992_u64),
    );
    assert_eq!(big.as_f64(), near.as_f64(), "the same f64");
    assert!(!json_eq_at(&big, &near, "", &none));
    // RerankingRank: `index` is an integer, `relevanceScore` an f64.
    let truth = json!({"index": 9_007_199_254_740_993_u64, "relevanceScore": 0.0});
    let floats = float_paths("RerankingRank", &truth);
    assert_eq!(floats, BTreeSet::from(["relevanceScore".to_string()]));
    let go = json!({"index": 9_007_199_254_740_993_u64, "relevanceScore": 0});
    assert!(json_eq_at(&go, &truth, "", &floats));
    let off = json!({"index": 9_007_199_254_740_992_u64, "relevanceScore": 0.0});
    assert!(!json_eq_at(&off, &truth, "", &floats));
    // An integer field written as 1.0 is a different JSON number.
    let int_as_float = json!({"index": 1.0, "relevanceScore": 0.0});
    assert!(!json_eq_at(
        &int_as_float,
        &json!({"index": 1, "relevanceScore": 0.0}),
        "",
        &floats
    ));
}

fn syn_field(wire: &str, ty: wire::WireTy) -> wire::WireField {
    wire::WireField {
        wire: wire.into(),
        rust: wire.into(),
        ty,
        presence: wire::Presence::default(),
        aliases: vec![],
        skip_fn: None,
        default_fn: None,
    }
}

fn syn_variant(name: &str, fields: Vec<wire::WireField>) -> wire::WireVariant {
    wire::WireVariant {
        rust: name.into(),
        wire: Some(name.into()),
        aliases: vec![],
        other: false,
        body: wire::VariantBody::Fields(fields),
    }
}

fn syn_ir(types: Vec<(&str, wire::WireBody)>) -> Ir {
    types
        .into_iter()
        .map(|(n, body)| {
            (
                n.to_string(),
                wire::WireType {
                    name: n.into(),
                    doc_source: String::new(),
                    body,
                },
            )
        })
        .collect()
}

fn prim(p: &str) -> wire::WireTy {
    wire::WireTy::Prim(p.into())
}

/// `json_eq_at` with float paths taken from the synthetic IR `m`.
fn syn_eq(m: &Ir, ty: &str, truth: &Value, got: &Value) -> bool {
    json_eq_at(truth, got, "", &float_paths_in(m, ty, truth))
}

/// A2: float paths inside an array and inside an Option.
#[test]
fn float_paths_inside_array_and_option() {
    let m = syn_ir(vec![(
        "R",
        wire::WireBody::Record {
            fields: vec![
                syn_field("xs", wire::WireTy::Array(Box::new(prim("f64")))),
                syn_field("o", wire::WireTy::Nullable(Box::new(prim("f64")))),
                syn_field("n", prim("u64")),
            ],
        },
    )]);
    let truth = json!({"xs": [1.0, 2.5], "o": 3.0, "n": 1});
    let paths = float_paths_in(&m, "R", &truth);
    assert_eq!(
        paths,
        ["o", "xs[0]", "xs[1]"]
            .iter()
            .map(ToString::to_string)
            .collect()
    );
    assert!(syn_eq(
        &m,
        "R",
        &truth,
        &json!({"xs": [1, 2.5], "o": 3, "n": 1})
    ));
    assert!(!syn_eq(
        &m,
        "R",
        &truth,
        &json!({"xs": [1.0, 2.5], "o": 3.0, "n": 1.0})
    ));
}

/// A2: a tagged union follows its tag; the same field is an integer in one
/// variant and a float in the other.
#[test]
fn float_paths_follow_the_tag() {
    let m = syn_ir(vec![(
        "U",
        wire::WireBody::Union {
            repr: wire::UnionRepr::Internal { tag: "type".into() },
            variants: vec![
                syn_variant("int", vec![syn_field("v", prim("u64"))]),
                syn_variant("float", vec![syn_field("v", prim("f64"))]),
            ],
        },
    )]);
    let big = json!({"type": "int", "v": 9_007_199_254_740_993_u64});
    assert!(!syn_eq(
        &m,
        "U",
        &big,
        &json!({"type": "int", "v": 9_007_199_254_740_992_u64})
    ));
    assert!(syn_eq(
        &m,
        "U",
        &json!({"type": "float", "v": 1.0}),
        &json!({"type": "float", "v": 1})
    ));
    assert!(!syn_eq(
        &m,
        "U",
        &json!({"type": "int", "v": 1}),
        &json!({"type": "int", "v": 1.0})
    ));
}

/// A2: an untagged union follows serde's first decoding variant: `v` is
/// `u64` in A and `f64` in B.
#[test]
fn float_paths_follow_the_first_decoding_untagged_variant() {
    let int_first = syn_ir(vec![(
        "U",
        wire::WireBody::Union {
            repr: wire::UnionRepr::Untagged,
            variants: vec![
                syn_variant("A", vec![syn_field("v", prim("u64"))]),
                syn_variant("B", vec![syn_field("v", prim("f64"))]),
            ],
        },
    )]);
    // 2^53+1 decodes as A (integer): exact.
    assert!(!syn_eq(
        &int_first,
        "U",
        &json!({"v": 9_007_199_254_740_993_u64}),
        &json!({"v": 9_007_199_254_740_992_u64})
    ));
    // 1.0 is not an integer, so it decodes as B (float): by value.
    assert!(syn_eq(
        &int_first,
        "U",
        &json!({"v": 1.0}),
        &json!({"v": 1})
    ));
    // 1 decodes as both A and B; serde takes A, so 1 vs 1.0 differs.
    assert!(!syn_eq(
        &int_first,
        "U",
        &json!({"v": 1}),
        &json!({"v": 1.0})
    ));
    let float_first = syn_ir(vec![(
        "U",
        wire::WireBody::Union {
            repr: wire::UnionRepr::Untagged,
            variants: vec![
                syn_variant("A", vec![syn_field("v", prim("f64"))]),
                syn_variant("B", vec![syn_field("v", prim("u64"))]),
            ],
        },
    )]);
    // 1 decodes as both; serde takes A (float) first, so by value.
    assert!(syn_eq(
        &float_first,
        "U",
        &json!({"v": 1}),
        &json!({"v": 1.0})
    ));
}

/// `int` (`uint64` / `int64`) Go field types become `float64`.
fn ints_as_float64(go_int: &'static str) -> impl Fn(String) -> String {
    move |s: String| {
        s.lines()
            .map(|l| {
                if l.contains("`json:") {
                    // `int64` is also a suffix of `uint64`.
                    let (u, i) = if go_int == "uint64" {
                        ("float64", "int64")
                    } else {
                        ("uint64", "float64")
                    };
                    l.replace("uint64", "\u{0}")
                        .replace("int64", i)
                        .replace('\u{0}', u)
                } else {
                    l.to_string()
                }
            })
            .collect::<Vec<_>>()
            .join("\n")
    }
}

/// Labels of the big-integer fixtures whose generated-Go round trip differs
/// from serde.
